import{_ as i,y as r,a as h,o as l,a2 as a,D as o,g as e,I as n}from"./chunks/framework.DCcmcJcL.js";const y=JSON.parse('{"title":"Themes & Sections","description":"","frontmatter":{},"headers":[],"relativePath":"appearance/themes.md","filePath":"appearance/themes.md","lastUpdated":1789441803000}'),c={name:"appearance/themes.md"};function d(u,t,g,p,m,f){const s=r("ImagePopup");return l(),h("div",null,[t[11]||(t[11]=a('<h1 id="themes-sections" tabindex="-1">Themes &amp; Sections <a class="header-anchor" href="#themes-sections" aria-label="Permalink to &quot;Themes &amp; Sections&quot;">​</a></h1><div class="feature-hero feature--theme"><span class="feature-hero__eyebrow">Storefront design</span><p class="feature-hero__lead">Choose the theme each channel uses, then build its storefront from sections such as banners, product carousels, content blocks and footer links, with a live preview beside you. Most changes wait until you publish.</p><div class="feature-hero__actions"><a class="feature-hero__btn feature-hero__btn--primary" href="#themes">Browse themes</a><a class="feature-hero__btn feature-hero__btn--ghost" href="#the-section-editor">Customize sections</a></div></div><div class="feature-cards feature--theme"><a class="feature-card" href="#themes"><span class="feature-card__icon feature-card__icon--layout" aria-hidden="true"></span><span class="feature-card__title">Themes</span><span class="feature-card__desc">See the themes installed on your store, activate one for each channel and find more in the theme store.</span><span class="feature-card__tag">Appearance &gt;&gt; Themes</span></a><a class="feature-card" href="#the-section-editor"><span class="feature-card__icon feature-card__icon--eye" aria-hidden="true"></span><span class="feature-card__title">Live section editor</span><span class="feature-card__desc">Reorder, switch on or off, duplicate and edit sections while the preview shows the result on desktop, tablet or mobile.</span><span class="feature-card__tag">Customize</span></a><a class="feature-card" href="/appearance/section-types.html"><span class="feature-card__icon feature-card__icon--blocks" aria-hidden="true"></span><span class="feature-card__title">Section types</span><span class="feature-card__desc">Image, product and category carousels, static content, service promises and footer links.</span><span class="feature-card__tag">Built-in types</span></a></div><p>The appearance of your storefront defines its look and feel, and it shapes the first impression a visitor gets. It has its own area in the admin panel, <strong>Appearance</strong>. A theme decides how the whole storefront looks. Sections are the blocks a theme&#39;s pages are built from, and you manage them for each channel.</p><h2 id="themes" tabindex="-1">Themes <a class="header-anchor" href="#themes" aria-label="Permalink to &quot;Themes&quot;">​</a></h2><p>Go to <strong>Appearance &gt;&gt; Themes</strong> to see the themes for your storefront, in two groups:</p><ul><li><strong>My Themes</strong>: themes installed on your store.</li><li><strong>Buy Themes</strong>: themes from the Bagisto theme store that aren&#39;t installed yet. <strong>View &amp; Buy</strong> appears when a theme has a store page, and <strong>Preview</strong> opens its demo. Both open in a new tab.</li></ul><p>Each card shows a picture, the theme&#39;s name and a short description, plus the author and version when they&#39;re known. An installed theme also shows where it&#39;s used: <strong>Active on every channel</strong>, <strong>Active on:</strong> followed by the channel names, or <strong>Not in use</strong>. A theme in use carries an <strong>Active</strong> badge.</p>',8)),o(s,{src:"/images/appearance/themes.png",alt:"Appearance >> Themes with the active Default theme under My Themes and themes on offer under Buy Themes"}),t[12]||(t[12]=a('<p>An installed theme has these buttons:</p><ul><li><strong>Customize</strong>: opens the section editor. Shown on a theme that&#39;s active on at least one channel.</li><li><strong>Activate</strong>: applies the theme to more channels. Shown until the theme is active on every channel.</li></ul><p>A theme under <strong>Buy Themes</strong> has to be installed on your store before you can activate it. Your developer or hosting partner installs it. Buttons your role has no permission for are hidden. Each channel uses one theme at a time; to set up channels, see <a href="./../settings/channels.html">Channels</a>.</p><h3 id="activate-a-theme" tabindex="-1">Activate a theme <a class="header-anchor" href="#activate-a-theme" aria-label="Permalink to &quot;Activate a theme&quot;">​</a></h3><ol><li>Go to <strong>Appearance &gt;&gt; Themes</strong>.</li><li>On a theme under <strong>My Themes</strong>, click <strong>Activate</strong>. The <strong>Activate Theme</strong> dialog opens.</li><li>In <strong>Channels</strong>, choose the channels that should use the theme. Hold Ctrl (Cmd on Mac) to pick more than one.</li><li>Read the warning, if one appears.</li><li>Click <strong>Activate</strong>.</li></ol><p>The <strong>Channels</strong> list shows only the channels that don&#39;t use the theme yet, and when only one is left, it&#39;s already selected. The theme goes live on the chosen channels straight away, and you see a message such as &quot;Default is now active on Default.&quot;</p><h3 id="sections-stay-with-their-theme" tabindex="-1">Sections stay with their theme <a class="header-anchor" href="#sections-stay-with-their-theme" aria-label="Permalink to &quot;Sections stay with their theme&quot;">​</a></h3><p>A channel&#39;s sections belong to the theme they were built for. When you switch a channel to another theme, the dialog warns that the channel has customizations built for its current theme: &quot;They stay saved, but will not appear while the new theme is active.&quot; Switch the channel back to show them again.</p><h2 id="the-section-editor" tabindex="-1">The section editor <a class="header-anchor" href="#the-section-editor" aria-label="Permalink to &quot;The section editor&quot;">​</a></h2><ol><li>Go to <strong>Appearance &gt;&gt; Themes</strong>.</li><li>On an active theme, click <strong>Customize</strong>. The <strong>Sections</strong> page opens.</li></ol>',10)),o(s,{src:"/images/appearance/section-editor.png",alt:"The section editor with the Sections list on the left and a live storefront preview on the right"}),t[13]||(t[13]=a('<p>The line under the title says what you&#39;re editing, for example &quot;Showing sections for the Default theme on the Default channel.&quot; The page has two parts:</p><ul><li><strong>The Sections list</strong> on the left shows the theme&#39;s sections in the order the storefront shows them, each with its name and type.</li><li><strong>The Preview</strong> on the right shows the channel&#39;s home page with your unpublished changes. Switch between <strong>Desktop</strong>, <strong>Tablet</strong> and <strong>Mobile</strong>, or click the reload icon to refresh it.</li></ul><p>When the channel has more than one language, choose the language at the top right. When your store has more than one channel, a channel selector appears beside it.</p><h3 id="what-you-can-do-in-the-list" tabindex="-1">What you can do in the list <a class="header-anchor" href="#what-you-can-do-in-the-list" aria-label="Permalink to &quot;What you can do in the list&quot;">​</a></h3><ul><li><strong>Edit</strong>: click a section&#39;s name. See <a href="#edit-a-section">Edit a section</a>.</li><li><strong>Reorder</strong>: drag a section by its handle.</li><li><strong>Switch on or off</strong>: use the switch on the row. The name of a section that&#39;s off is struck through.</li><li><strong>Duplicate</strong>: open the <strong>⋯</strong> menu and click <strong>Duplicate</strong>. The copy is placed below the original, with <strong>Copy</strong> added to its name. It shows switched on with an unsaved change, so it goes live when you publish.</li><li><strong>Delete</strong>: open the <strong>⋯</strong> menu, click <strong>Delete</strong> and confirm.</li></ul>',5)),o(s,{src:"/images/appearance/section-actions.png",alt:"The ⋯ menu of a section row open, with Duplicate and Delete"}),t[14]||(t[14]=e("p",null,[e("strong",null,"Footer Links"),n(" is pinned to the bottom of the page, so it has no drag handle and can't be duplicated.")],-1)),t[15]||(t[15]=e("div",{class:"warning custom-block"},[e("p",{class:"custom-block-title"},"Deleting can't be undone"),e("p",null,"A deleted section disappears from the storefront straight away. Deleting isn't held for publishing. To take a section off the storefront and keep it, switch it off instead.")],-1)),t[16]||(t[16]=e("h3",{id:"edit-a-section",tabindex:"-1"},[n("Edit a section "),e("a",{class:"header-anchor",href:"#edit-a-section","aria-label":'Permalink to "Edit a section"'},"​")],-1)),e("ol",null,[t[1]||(t[1]=e("li",null,[e("p",null,[n("In the "),e("strong",null,"Sections"),n(" list, click the section's name. A panel opens with the section's fields, and the preview moves beside it and highlights the section.")])],-1)),t[2]||(t[2]=e("li",null,[e("p",null,[n("Change the fields. Each type's fields are described in "),e("a",{href:"./section-types.html"},"Section types"),n(".")])],-1)),e("li",null,[t[0]||(t[0]=e("p",null,"Check the preview. Your changes are saved as a draft while you type, and the preview reloads to show them.",-1)),o(s,{src:"/images/appearance/section-edit.png",alt:"A Product Carousel section open for editing, with the section highlighted in the preview"})]),t[3]||(t[3]=e("li",null,[e("p",null,"Close the panel.")],-1)),t[4]||(t[4]=e("li",null,[e("p",null,[n("Click "),e("strong",null,"Publish"),n(" when you're ready for shoppers to see the changes.")])],-1))]),t[17]||(t[17]=a('<h3 id="most-changes-wait-until-you-publish" tabindex="-1">Most changes wait until you publish <a class="header-anchor" href="#most-changes-wait-until-you-publish" aria-label="Permalink to &quot;Most changes wait until you publish&quot;">​</a></h3><p>These changes are held as unsaved changes until you publish them:</p><ul><li>Changes to a section&#39;s fields, in any language.</li><li>Switching a section on or off.</li><li>A new order of sections.</li></ul><p>While changes are waiting, the <strong>Sections</strong> list shows how many there are, such as &quot;2 Unsaved changes&quot;, and each changed row is marked with a dot. <strong>Discard</strong> and <strong>Publish</strong> appear at the top of the page, with the count on <strong>Publish</strong>:</p><ul><li><strong>Publish</strong>: sends every unsaved change for this theme and channel, in every language, to the storefront.</li><li><strong>Discard</strong>: throws away every unsaved change, without asking you to confirm. The list and the preview go back to what&#39;s live.</li></ul><div class="info custom-block"><p class="custom-block-title">With more than one channel</p><p>After you publish or discard, check the storefront of the channel you edited.</p></div><p>Published changes show on the storefront straight away: on most pages for <strong>Footer Links</strong> and <strong>Services Content</strong>, and on the home page for the other types.</p><h3 id="new-and-duplicated-sections" tabindex="-1">New and duplicated sections <a class="header-anchor" href="#new-and-duplicated-sections" aria-label="Permalink to &quot;New and duplicated sections&quot;">​</a></h3><p>Creating or duplicating a section saves it straight away, still hidden from shoppers. In the list it shows switched on with an unsaved change, so <strong>Publish</strong> puts it live. To keep it hidden, switch it off before you publish. <strong>Discard</strong> doesn&#39;t delete a new section; it leaves it switched off.</p><h3 id="languages-and-channels" tabindex="-1">Languages and channels <a class="header-anchor" href="#languages-and-channels" aria-label="Permalink to &quot;Languages and channels&quot;">​</a></h3><ul><li><strong>Each language has its own content.</strong> Choose the language at the top before you edit a section&#39;s fields. Switching a section on or off, and the order of sections, apply to every language.</li><li><strong>Each channel has its own sections.</strong> Choose another channel at the top to edit its sections, which belong to the theme that channel uses.</li></ul><h3 id="create-a-section" tabindex="-1">Create a section <a class="header-anchor" href="#create-a-section" aria-label="Permalink to &quot;Create a section&quot;">​</a></h3>',12)),e("ol",null,[t[6]||(t[6]=e("li",null,[e("p",null,[n("In the section editor, click "),e("strong",null,"+"),n(" beside "),e("strong",null,"Sections"),n(". The "),e("strong",null,"Create Section"),n(" panel opens.")])],-1)),t[7]||(t[7]=e("li",null,[e("p",null,[n("Under "),e("strong",null,"Type"),n(", click the type of section.")])],-1)),e("li",null,[t[5]||(t[5]=e("p",null,[n("Enter a "),e("strong",null,"Name"),n(". It's shown in the "),e("strong",null,"Sections"),n(" list, not to shoppers.")],-1)),o(s,{src:"/images/appearance/create-section.png",alt:"The Create Section panel with Product Carousel chosen and the name Summer Picks"})]),t[8]||(t[8]=e("li",null,[e("p",null,[n("Click "),e("strong",null,"Save Section"),n(". The section is added at the bottom of the list, above "),e("strong",null,"Footer Links"),n(", shown switched on with an unsaved change, and its fields open.")])],-1)),t[9]||(t[9]=e("li",null,[e("p",null,"Fill in the fields.")],-1)),t[10]||(t[10]=e("li",null,[e("p",null,[n("Click "),e("strong",null,"Publish"),n(".")])],-1))]),t[18]||(t[18]=a('<p>A channel can have only one <strong>Footer Links</strong> section, so that type isn&#39;t offered once the channel has one.</p><h2 id="section-types" tabindex="-1">Section types <a class="header-anchor" href="#section-types" aria-label="Permalink to &quot;Section types&quot;">​</a></h2><p>The default theme offers six built-in types: <strong>Image Carousel</strong>, <strong>Product Carousel</strong>, <strong>Category Carousel</strong>, <strong>Static Content</strong>, <strong>Services Content</strong> and <strong>Footer Links</strong>. A theme you install can add types of its own, or offer only some of them. The fields of each type are described in <a href="./section-types.html">Section types</a>.</p><h2 id="upgrading-from-an-earlier-version" tabindex="-1">Upgrading from an earlier version <a class="header-anchor" href="#upgrading-from-an-earlier-version" aria-label="Permalink to &quot;Upgrading from an earlier version&quot;">​</a></h2><p>If you used <strong>Settings &gt;&gt; Themes</strong> before, that screen has moved. Theme customizations are now sections, and they live under <strong>Appearance</strong>. Existing customizations are carried over, so you don&#39;t need to recreate them.</p>',5))])}const b=i(c,[["render",d]]);export{y as __pageData,b as default};
